     "acompanhar": "Checagens curtas e frequentes, de dez a quinze minutos por semana, olhando marcos e números, não cada passo. Uma mensagem rápida no meio da semana ajuda a pegar desvios cedo. Evite pedir relatórios longos: peça três linhas e um número.",
     "exemplo": "Numa loja de materiais de construção, em vez de dizer \"cuida da campanha de reforma\", combine: \"Quero 40 orçamentos de reforma fechados até 30 de novembro, com desconto máximo de 8% sem falar comigo. Você escolhe as ações. Toda sexta me manda três linhas: quantos orçamentos, quantos fechados e o que travou\". A pessoa ganha liberdade para criar e você ganha visibilidade sem precisar vigiar.",
